# ---------- utilitarios ----------
def _asset_bytes(b64: str) -> bytes:
    return base64.b64decode(b64.encode('ascii'))


def _sanitize_text(value: Any) -> str:
    s = str(value or '').replace('\r', ' ').strip()
    # Nomenclatura institucional pedida: nada de DENARC / DIC isolado.
    s = re.sub(r'(?i)\bDENARC\b', 'POLÍCIA FEDERAL', s)
    s = re.sub(r'(?i)\bDIC\b', 'DICOR', s)
    s = re.sub(r'[ \t]+', ' ', s)
    return s


def _esc(value: Any) -> str:
    return html.escape(_sanitize_text(value), quote=False)


def _norm(value: Any) -> str:
    s = unicodedata.normalize('NFKD', str(value or '').lower())
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    return re.sub(r'[^a-z0-9]+', ' ', s).strip()


def _fmt_timestamp(raw: Any) -> str:
    txt = str(raw or '').strip()
    if not txt:
        return ''
    dt = None
    try:
        dt = datetime.fromisoformat(txt.replace('Z', '+00:00'))
    except Exception:
        m = re.search(r'(\d{2})/(\d{2})/(\d{4}).*?(\d{2}):(\d{2})', txt)
        if m:
            return f'{m.group(1)}/{m.group(2)}/{m.group(3)} às {m.group(4)}:{m.group(5)}'
        m = re.search(r'(\d{4})-(\d{2})-(\d{2}).*?(\d{2}):(\d{2})', txt)
        if m:
            return f'{m.group(3)}/{m.group(2)}/{m.group(1)} às {m.group(4)}:{m.group(5)}'
        return txt[:48]
    try:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        from zoneinfo import ZoneInfo
        dt = dt.astimezone(ZoneInfo('America/Sao_Paulo'))
    except Exception:
        pass
    return dt.strftime('%d/%m/%Y às %H:%M')


def _iter_media(section: Dict[str, Any]) -> Iterable[Dict[str, Any]]:
    for item in list(section.get('images') or []):
        if isinstance(item, dict):
            yield item
    for group in list(section.get('subgroups') or []):
        if isinstance(group, dict):
            for item in list(group.get('images') or []):
                if isinstance(item, dict):
                    yield item
    for p in list(section.get('people') or []):
        if isinstance(p, dict) and isinstance(p.get('foto'), dict):
            yield p['foto']
    inf = section.get('informante')
    if isinstance(inf, dict):
        for key in ('foto', 'documento'):
            if isinstance(inf.get(key), dict):
                yield inf[key]
    for crime in list(section.get('crimes') or []):
        if isinstance(crime, dict):
            for item in list(crime.get('provas') or []):
                if isinstance(item, dict):
                    yield item


def _timestamp_section(section: Dict[str, Any]) -> str:
    # Exibe uma unica vez, sempre a partir da mensagem/evidencia real.
    for media in _iter_media(section):
        ts = _fmt_timestamp(media.get('data') or media.get('created_at') or media.get('timestamp') or media.get('data_mensagem'))
        if ts:
            return ts
    return ''


def _dedupe_media(items: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    seen = set()
    for item in items:
        if not isinstance(item, dict):
            continue
        key = (
            str(item.get('mensagem_id') or item.get('message_id') or ''),
            str(item.get('url') or item.get('proxy_url') or ''),
            str(item.get('local') or item.get('arquivo') or item.get('path') or '')
        )
        if key in seen:
            continue
        seen.add(key)
        out.append(item)
    return out


def _materialize(media: Dict[str, Any], cache_dir: Path, materializer=None) -> Optional[Path]:
    if not isinstance(media, dict):
        return None
    for key in ('path', 'local_path', 'arquivo', 'caminho', 'local'):
        value = media.get(key)
        if value:
            try:
                p = Path(str(value))
                if p.exists() and p.is_file() and p.stat().st_size > 0:
                    return p
            except Exception:
                pass
    if callable(materializer):
        try:
            p = materializer(media, cache_dir)
            if p:
                p = Path(str(p))
                if p.exists() and p.is_file() and p.stat().st_size > 0:
                    return p
        except Exception as exc:
            print(f'⚠️ V161 midia nao materializada: {type(exc).__name__}: {exc}', flush=True)
    return None


def _rl_image(path: Path, max_w: float, max_h: float) -> Optional[RLImage]:
    try:
        from PIL import Image as PILImage
        with PILImage.open(path) as im:
            iw, ih = im.size
        if iw <= 0 or ih <= 0:
            return None
        scale = min(max_w / iw, max_h / ih)
        return RLImage(str(path), width=iw*scale, height=ih*scale)
    except Exception:
        return None


