# ---------- pagina / cabecalho ----------
def _header_drawer(border: bytes, pf: bytes, dicor: bytes, wm: bytes):
    def draw(c, doc):
        W, H = A4
        c.saveState()
        c.setFillColor(colors.white)
        c.rect(0, 0, W, H, fill=1, stroke=0)
        c.drawImage(ImageReader(io.BytesIO(border)), 4, 4, width=W-8, height=H-8, mask='auto')
        # Marca d'agua grande, exatamente na linha visual do modelo anexado.
        try:
            c.setFillAlpha(0.13)
        except Exception:
            pass
        c.drawImage(ImageReader(io.BytesIO(wm)), W/2-164, H/2-166, width=328, height=328, mask='auto')
        try:
            c.setFillAlpha(1)
        except Exception:
            pass
        # Brasoes largos, sem invadir titulo ou moldura.
        c.drawImage(ImageReader(io.BytesIO(pf)), 37, H-126, width=86, height=96, preserveAspectRatio=False, mask='auto')
        c.drawImage(ImageReader(io.BytesIO(dicor)), W-123, H-126, width=86, height=96, preserveAspectRatio=False, mask='auto')
        c.setFillColor(HexColor('#222222'))
        c.setFont('Helvetica-BoldOblique', 25.5)
        c.drawCentredString(W/2, H-55, 'POLÍCIA FEDERAL - DICOR')
        c.setFont('Helvetica-BoldOblique', 21.5)
        c.drawCentredString(W/2, H-88, 'DO ESTADO DA CAPITAL')
        c.drawCentredString(W/2, H-118, 'MORADA DO VALLEY')
        c.restoreState()
    return draw


def _bullet(text: Any, styles) -> Paragraph:
    return Paragraph('• ' + _esc(text), styles['body'])


def _label(label: str, styles) -> Paragraph:
    return Paragraph(_esc(label), styles['label'])


def _clean_summary(summary: str, ts: str) -> str:
    text = _sanitize_text(summary)
    if ts:
        # Evita repetir a mesma data/hora na descricao.
        text = text.replace(ts, '').replace('  ', ' ').strip(' -;,.')
    return text


# ---------- grids de imagens ----------
def _media_cell(media: Dict[str, Any], path: Path, cell_w: float, max_h: float, styles, fallback_caption: str) -> List[Any]:
    img = _rl_image(path, cell_w-8, max_h)
    cap = _sanitize_text(media.get('caption') or media.get('nome') or fallback_caption)
    cell: List[Any] = [Spacer(1, 2)]
    if img:
        cell += [img, Spacer(1, 4)]
    cell += [Paragraph(_esc(cap), styles['caption']), Spacer(1, 2)]
    return cell


def _media_grid(media_list: List[Dict[str, Any]], cache: Path, materializer, styles, prefix='EVIDÊNCIA', columns=2, max_img_h=155) -> Optional[Table]:
    valid: List[Tuple[Dict[str, Any], Path]] = []
    for media in _dedupe_media(media_list):
        p = _materialize(media, cache, materializer)
        if p:
            valid.append((media, p))
    if not valid:
        return None
    columns = max(1, min(int(columns or 1), 4))
    usable = 18.0*cm
    gap = 0.20*cm
    cell_w = (usable-gap*(columns-1))/columns
    rows=[]
    for start in range(0,len(valid),columns):
        row=[]
        for j in range(columns):
            idx=start+j
            if idx>=len(valid):
                row.append('')
                continue
            media,p=valid[idx]
            row.append(_media_cell(media,p,cell_w,max_img_h,styles,f'{prefix} {idx+1:02d}'))
        rows.append(row)
    t=Table(rows,colWidths=[cell_w]*columns,hAlign='CENTER',splitByRow=1)
    # Sem cartoes cinza: somente a linha fina semelhante ao documento anexado.
    t.setStyle(TableStyle([
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('ALIGN',(0,0),(-1,-1),'CENTER'),
        ('BOX',(0,0),(-1,-1),0.55,HexColor('#8098A0')),
        ('INNERGRID',(0,0),(-1,-1),0.40,HexColor('#A8B6BA')),
        ('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),
        ('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),
    ]))
    return t


def _people_grid(people: List[Dict[str, Any]], cache: Path, materializer, styles, leadership_only=False, members_only=False) -> Optional[Table]:
    valid=[]
    for person in list(people or []):
        if not isinstance(person,dict):
            continue
        role=_sanitize_text(person.get('cargo') or 'Membro')
        n=_norm(role)
        is_lead=any(k in n for k in ('lider','vice','gerente'))
        if leadership_only and not is_lead:
            continue
        if members_only and is_lead:
            continue
        foto=person.get('foto') if isinstance(person.get('foto'),dict) else None
        p=_materialize(foto,cache,materializer) if foto else None
        if not p:
            continue
        valid.append((person,p))
    if not valid:
        return None
    cols=4 if len(valid)>=4 else min(3,len(valid))
    usable=18.0*cm
    gap=0.16*cm
    cell_w=(usable-gap*(cols-1))/cols
    rows=[]
    for start in range(0,len(valid),cols):
        row=[]
        for j in range(cols):
            idx=start+j
            if idx>=len(valid):
                row.append(''); continue
            person,p=valid[idx]
            role=_sanitize_text(person.get('cargo') or 'Membro').upper()
            name=_sanitize_text(person.get('nome') or 'Não informado')
            rg=_sanitize_text(person.get('rg') or 'Não informado')
            img=_rl_image(p,cell_w-8,5.65*cm)
            cell=[Paragraph(_esc(role),styles['card_role']),Spacer(1,4)]
            if img: cell += [img,Spacer(1,5)]
            cell += [Paragraph(_esc(name),styles['card_name']),Paragraph('RG: '+_esc(rg),styles['card_rg'])]
            row.append(cell)
        rows.append(row)
    t=Table(rows,colWidths=[cell_w]*cols,hAlign='CENTER',splitByRow=1)
    t.setStyle(TableStyle([
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),('ALIGN',(0,0),(-1,-1),'CENTER'),
        ('BOX',(0,0),(-1,-1),0.50,HexColor('#8098A0')),
        ('INNERGRID',(0,0),(-1,-1),0.38,HexColor('#A8B6BA')),
        ('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),
        ('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),
    ]))
    return t


