def _section_intro(sec: Dict[str,Any], styles) -> List[Any]:
    code=str(sec.get('code') or '').zfill(2)
    flow=[Paragraph(_esc(_SECTION_NAMES.get(code, f'{code}. '+_sanitize_text(sec.get('title') or 'SEÇÃO'))),styles['section'])]
    ts=_timestamp_section(sec)
    flow += [_label('Data e Local:',styles)]
    if ts:
        flow += [_bullet(f'Registro da mensagem: {ts}.',styles)]
    else:
        flow += [_bullet('Registro preservado no procedimento investigativo.',styles)]
    summary=_clean_summary(sec.get('summary') or '',ts) or _DEFAULT_DESC.get(code,'')
    if summary:
        flow += [_label('Descrição:',styles),_bullet(summary,styles)]
    relation=_RELATION.get(code)
    if relation:
        flow += [_label('Relação com o Processo:',styles),_bullet(relation,styles)]
    return flow


def _image_columns(count: int) -> int:
    if count <= 1: return 1
    if count <= 4: return 2
    return 3


def _ingredients_groups(sec: Dict[str,Any]) -> Tuple[List[Dict[str,Any]],List[Dict[str,Any]]]:
    groups=[g for g in list(sec.get('subgroups') or []) if isinstance(g,dict)]
    ingredients:List[Dict[str,Any]]=[]
    products:List[Dict[str,Any]]=[]
    undecided=[]
    for g in groups:
        imgs=[m for m in list(g.get('images') or []) if isinstance(m,dict)]
        n=_norm(g.get('label'))
        if 'ingrediente' in n or 'insumo' in n:
            ingredients.extend(imgs)
        elif 'produto' in n:
            products.extend(imgs)
        else:
            undecided.append(imgs)
    # Regra solicitada: grupos com 4+ evidencias = ingredientes; grupos com 1-2 = produto.
    for imgs in undecided:
        if len(imgs)>=4:
            ingredients.extend(imgs)
        elif 1<=len(imgs)<=2:
            products.extend(imgs)
        else:
            ingredients.extend(imgs)
    # Fallback para payload legado sem subgrupos.
    if not groups:
        flat=[m for m in list(sec.get('images') or []) if isinstance(m,dict)]
        if len(flat)>=5:
            ingredients.extend(flat[:-1]); products.append(flat[-1])
        else:
            ingredients.extend(flat)
    return _dedupe_media(ingredients),_dedupe_media(products)


def _caption_group(items: List[Dict[str,Any]], kind: str) -> List[Dict[str,Any]]:
    out=[]
    for i,m in enumerate(items,1):
        mm=dict(m)
        original=_sanitize_text(mm.get('caption') or mm.get('nome') or '')
        n=_norm(original)
        generic = not original or n in {'ingredientes','ingrediente','produto final','produto','registro'}
        if kind=='ingredient':
            mm['caption'] = f'INGREDIENTE {i:02d}' if generic else f'INGREDIENTE {i:02d} - {original}'
        else:
            mm['caption'] = f'PRODUTO FINAL {i:02d}' if generic else f'PRODUTO FINAL {i:02d} - {original}'
        out.append(mm)
    return out


def _flow_section(sec: Dict[str,Any], cache: Path, materializer, styles) -> List[Any]:
    code=str(sec.get('code') or '').zfill(2)
    flow=_section_intro(sec,styles)

    extra=_sanitize_text(sec.get('extra_text') or '')
    if extra and code not in {'02','03'}:
        flow += [_label('Informações complementares:',styles),_bullet(extra,styles)]

    if code=='02':
        flow += [_label('Mídia de Apoio:',styles)]
        t=_people_grid(list(sec.get('people') or []),cache,materializer,styles,leadership_only=True)
        if t: flow.append(t)
        else: flow.append(_bullet('Nenhuma foto de Líder, Vice-Líder ou Gerente foi registrada nesta seção.',styles))
        return flow

    if code=='03':
        flow += [_label('Mídia de Apoio:',styles)]
        t=_people_grid(list(sec.get('people') or []),cache,materializer,styles,members_only=True)
        if not t:
            # payload de membros normalmente já não contém lideranças; tenta novamente sem filtro.
            t=_people_grid(list(sec.get('people') or []),cache,materializer,styles)
        if t: flow.append(t)
        else: flow.append(_bullet('Nenhuma foto de membro foi registrada nesta seção.',styles))
        return flow

    if code=='04':
        lines=list(sec.get('field_lines') or [])
        if lines:
            flow += [_label('Dado operacional:',styles)]
            for item in lines:
                if isinstance(item,(list,tuple)) and len(item)>=2:
                    flow += [_bullet(f'{_sanitize_text(item[0])}: {_sanitize_text(item[1])}',styles)]
        return flow

    if code=='06':
        crimes=[c for c in list(sec.get('crimes') or []) if isinstance(c,dict)]
        flow += [_label('Mídia de Apoio:',styles)]
        if not crimes:
            flow += [_bullet('Nenhum registro de crime com prova visual foi anexado nesta seção.',styles)]
            return flow
        for idx,crime in enumerate(crimes,1):
            flow += [Paragraph(f'<b>Registro {idx:02d}:</b> {_esc(crime.get("descricao") or "Crime registrado")}',styles['plain'])]
            provas=list(crime.get('provas') or [])
            t=_media_grid(provas,cache,materializer,styles,prefix=f'PROVA {idx:02d}',columns=_image_columns(len(provas)),max_img_h=135)
            if t: flow += [t,Spacer(1,6)]
        return flow

    if code=='11':
        ingredients,products=_ingredients_groups(sec)
        flow += [_label('Mídia de Apoio:',styles)]
        if ingredients:
            ing=_caption_group(ingredients,'ingredient')
            flow += [Paragraph('<b>INGREDIENTES</b> - grupo de insumos registrados.',styles['plain'])]
            t=_media_grid(ing,cache,materializer,styles,prefix='INGREDIENTE',columns=_image_columns(len(ing)),max_img_h=145)
            if t: flow += [t,Spacer(1,8)]
        if products:
            prod=_caption_group(products,'product')
            flow += [Paragraph('<b>PRODUTO FINAL</b> - resultado final registrado.',styles['plain'])]
            t=_media_grid(prod,cache,materializer,styles,prefix='PRODUTO FINAL',columns=_image_columns(len(prod)),max_img_h=155)
            if t: flow += [t]
        if not ingredients and not products:
            flow += [_bullet('Nenhuma evidência visual de ingredientes ou produto final foi materializada.',styles)]
        return flow

    if code=='12':
        inf=sec.get('informante') if isinstance(sec.get('informante'),dict) else {}
        if inf:
            flow += [_label('Identificação:',styles),_bullet(f'Nome: {_sanitize_text(inf.get("nome") or "Não informado")} | RG: {_sanitize_text(inf.get("rg") or "Não informado")}',styles)]

    groups=[g for g in list(sec.get('subgroups') or []) if isinstance(g,dict)]
    if groups:
        flow += [_label('Mídia de Apoio:',styles)]
        for g in groups:
            label=_sanitize_text(g.get('label') or 'EVIDÊNCIAS').upper()
            imgs=list(g.get('images') or [])
            if not imgs: continue
            flow += [Paragraph('<b>'+_esc(label)+'</b>',styles['plain'])]
            t=_media_grid(imgs,cache,materializer,styles,prefix=label,columns=_image_columns(len(imgs)),max_img_h=140 if len(imgs)>2 else 175)
            if t: flow += [t,Spacer(1,7)]
    else:
        imgs=list(sec.get('images') or [])
        flow += [_label('Mídia de Apoio:',styles)]
        t=_media_grid(imgs,cache,materializer,styles,prefix=_sanitize_text(sec.get('title') or 'EVIDÊNCIA'),columns=_image_columns(len(imgs)),max_img_h=185 if len(imgs)<=2 else 140)
        if t: flow.append(t)
        else: flow.append(_bullet('Nenhuma evidência visual foi anexada nesta seção.',styles))
    return flow


def _first_pages(meta: Dict[str,Any], sections: Dict[str,Dict[str,Any]], styles) -> List[Any]:
    story:List[Any]=[]
    pedido=_sanitize_text(meta.get('pedido_numero') or meta.get('numero') or 'Não informado')
    data=_sanitize_text(meta.get('pedido_data') or meta.get('data_expedicao') or '')
    if not data or _norm(data)=='nao informado':
        try:
            from zoneinfo import ZoneInfo
            data=datetime.now(ZoneInfo('America/Sao_Paulo')).strftime('%d/%m/%Y')
        except Exception:
            data=datetime.now().strftime('%d/%m/%Y')
    processo=_sanitize_text(meta.get('processo') or 'Não informado')
    comunidade=_sanitize_text(meta.get('comunidade') or 'organização investigada')
    local=_sanitize_text(meta.get('pedido_local') or meta.get('local_pacificacao') or comunidade or 'Não informado')
    cidade=_sanitize_text(meta.get('cidade') or 'Capital Morada do Valley')

    for label,value in (
        ('Nº do Pedido de Pacificação',pedido),('Data de Expedição',data),('Nº do Processo',processo)
    ):
        story.append(Paragraph(f'<b>{_esc(label)}:</b> &nbsp;&nbsp; <b>{_esc(value)}</b>',styles['plain']))
    story += [Spacer(1,16),_label('Requerente:',styles),_bullet('Polícia Federal - DICOR, por intermédio de Buiu Gomes - Delegado Geral.',styles),Spacer(1,8)]
    story += [_label('Localização:',styles)]
    story += [_bullet(f'A Polícia Federal de {cidade}, por intermédio da Diretoria de Investigação e Combate ao Crime Organizado - DICOR, requer a concessão do presente MANDADO DE PACIFICAÇÃO, visando a manutenção da ordem e o cumprimento das determinações aplicáveis ao procedimento.',styles)]
    story += [_bullet(f'Dessa forma, solicita-se autorização para proceder com a busca e pacificação no local denominado “{local}”, vinculado à organização {comunidade}, incluindo os pontos e instalações documentados no dossiê operacional.',styles),PageBreak()]

    story += [Paragraph('DISPOSIÇÕES DO MANDADO',styles['section'])]
    disposicoes=[
        'Fica autorizada a busca nos pontos e instalações vinculados à organização e documentados no procedimento, inclusive compartimentos de armazenamento identificados.',
        'Nenhum documento ou objeto pertencente a terceiros, familiares ou residentes sem vínculo com os fatos investigados deverá ser apreendido.',
        'Deverá ser solicitada a presença de representante jurídico quando cabível, observadas as regras internas aplicáveis ao procedimento.',
        'Caso sejam identificados materiais probatórios adicionais relevantes, deverá ser formalizada a ampliação do registro e sua vinculação ao processo.',
        'Fica autorizada a abertura de cofres, baús e demais compartimentos vinculados à investigação caso não sejam voluntariamente disponibilizados.',
        'Investigados eventualmente detidos deverão ser apresentados à autoridade competente conforme o protocolo vigente.',
    ]
    for d in disposicoes: story.append(_bullet(d,styles))
    story.append(PageBreak())

    radio='Não informada'
    sec4=sections.get('04') or {}
    for line in list(sec4.get('field_lines') or []):
        if isinstance(line,(list,tuple)) and len(line)>=2:
            radio=_sanitize_text(line[1])
            break
    story += [Paragraph('PLANEJAMENTO OPERACIONAL',styles['section']),Paragraph('Para garantir o sucesso da pacificação, a operação contará com:',styles['plain'])]
    for lbl,txt in (
        ('Efetivo envolvido','Agentes da DICOR, equipes táticas especializadas e reforço policial de apoio.'),
        ('Recursos utilizados','Viaturas de apoio, drones para reconhecimento e recursos de observação aérea quando disponíveis.'),
        ('Estratégia de abordagem','Divisão da área em setores, controle dos principais acessos e avaliação prévia dos pontos registrados nas vistas aéreas.'),
        ('Medidas de proteção','Aviso e orientação à população local quando a situação operacional permitir, suporte médico em caso de necessidade e preservação de terceiros sem vínculo com a investigação.'),
        ('Dado operacional identificado',f'Frequência de rádio registrada na investigação: {radio}.'),
    ):
        story += [_label(lbl+':',styles),_bullet(txt,styles)]
    story.append(PageBreak())
    return story


def _motivation_page(sections: Dict[str,Dict[str,Any]], styles) -> List[Any]:
    flow=[Paragraph('MOTIVAÇÃO',styles['section']),Paragraph('Este pedido fundamenta-se nas informações consolidadas no dossiê:',styles['plain'])]
    crimes=sections.get('06') or {}
    crime_items=[c for c in list(crimes.get('crimes') or []) if isinstance(c,dict)]
    if crime_items:
        flow += [_label('Enquadramentos registrados:',styles)]
        for c in crime_items:
            flow += [_bullet(_sanitize_text(c.get('descricao') or 'Crime registrado.'),styles)]
    flow += [_label('Além disso, a pacificação é solicitada considerando:',styles)]
    bullets=[
        'Estrutura hierárquica identificada por painel, lideranças e membros cadastrados.',
        'Local da organização e vistas aéreas documentados para planejamento territorial.',
        'Rotas de farm e de produção registradas com referências geográficas.',
        'Baús de membros e de liderança individualizados na investigação.',
        'Ingredientes e produto final vinculados ao material investigativo e apresentados em grupos separados.',
    ]
    for b in bullets: flow += [_bullet(b,styles)]
    sec13=sections.get('13') or {}
    if not list(sec13.get('images') or []):
        flow += [_label('Observação complementar:',styles),_bullet('A residência do líder não foi identificada no material consolidado; o dossiê registra expressamente essa ausência, sem criar informação substitutiva.',styles)]
    return flow


def _signature_page(meta: Dict[str,Any], styles) -> List[Any]:
    """Página final com três blocos de assinatura sempre visíveis.

    Mantém o visual V161, mas evita depender de uma tabela de três colunas
    apertada. Os dois delegados ficam lado a lado e o agente responsável fica
    centralizado abaixo, garantindo que nenhum bloco seja empurrado para fora
    da área útil da página.
    """
    pedido=_sanitize_text(meta.get('pedido_numero') or meta.get('numero') or 'Não informado')
    local=_sanitize_text(meta.get('pedido_local') or meta.get('comunidade') or 'área indicada no procedimento')
    responsavel=_sanitize_text(
        meta.get('agente_responsavel')
        or meta.get('responsavel_nome')
        or meta.get('responsavel')
        or meta.get('criador_nome')
        or meta.get('autor_nome')
        or meta.get('autor')
        or 'Agente responsável'
    )
    try:
        from zoneinfo import ZoneInfo
        hoje=datetime.now(ZoneInfo('America/Sao_Paulo')).strftime('%d/%m/%Y')
    except Exception:
        hoje=datetime.now().strftime('%d/%m/%Y')

    flow=[Paragraph('PROVAS E DOCUMENTAÇÕES',styles['section'])]
    flow += [_bullet(
        f'Com base nas provas apresentadas e nas informações consolidadas no processo, solicita-se a manutenção do Pedido de Pacificação {pedido} e a adoção das medidas necessárias à segurança operacional na área indicada como “{local}”.',
        styles,
    )]
    flow += [
        Spacer(1,8),
        Paragraph('<b>RESPONSÁVEIS PELO PROCEDIMENTO</b>',styles['tiny']),
        Spacer(1,3),
        Paragraph('Buiu Gomes - Delegado Geral',styles['tiny']),
        Paragraph('Arthur Fleker - Delegado DICOR',styles['tiny']),
        Paragraph(f'Capital Morada do Valley - {hoje}',styles['tiny']),
        Spacer(1,36),
    ]

    def _sig_block(nome: str, cargo: str):
        nome_limpo=_sanitize_text(nome)
        return [
            Paragraph(nome_limpo,styles['sig_name']),
            Spacer(1,4),
            Paragraph(nome_limpo.upper(),styles['sig_caps']),
            Paragraph(cargo,styles['sig_caps']),
            Paragraph('POLÍCIA FEDERAL - DICOR',styles['sig_caps']),
        ]

    delegados=Table(
        [[_sig_block('Buiu Gomes','DELEGADO GERAL'), _sig_block('Arthur Fleker','DELEGADO DICOR')]],
        colWidths=[8.05*cm,8.05*cm],
        hAlign='CENTER',
    )
    delegados.setStyle(TableStyle([
        ('VALIGN',(0,0),(-1,-1),'TOP'),
        ('ALIGN',(0,0),(-1,-1),'CENTER'),
        ('LINEABOVE',(0,0),(0,0),0.85,HexColor('#444444')),
        ('LINEABOVE',(1,0),(1,0),0.85,HexColor('#444444')),
        ('LEFTPADDING',(0,0),(-1,-1),5),
        ('RIGHTPADDING',(0,0),(-1,-1),5),
        ('TOPPADDING',(0,0),(-1,-1),8),
    ]))
    flow.append(KeepTogether([delegados]))

    flow.append(Spacer(1,52))
    agente=Table(
        [[_sig_block(responsavel,'AGENTE RESPONSÁVEL')]],
        colWidths=[8.05*cm],
        hAlign='CENTER',
    )
    agente.setStyle(TableStyle([
        ('VALIGN',(0,0),(0,0),'TOP'),
        ('ALIGN',(0,0),(0,0),'CENTER'),
        ('LINEABOVE',(0,0),(0,0),0.85,HexColor('#444444')),
        ('LEFTPADDING',(0,0),(0,0),5),
        ('RIGHTPADDING',(0,0),(0,0),5),
        ('TOPPADDING',(0,0),(0,0),8),
    ]))
    flow.append(KeepTogether([agente]))
    return flow


def render_payload(payload: Dict[str,Any], caminho_pdf: Path, materializer=None) -> None:
    if not isinstance(payload,dict):
        raise RuntimeError('V161: payload do dossie ausente.')
    sections={str(s.get('code') or '').zfill(2):s for s in list(payload.get('sections') or []) if isinstance(s,dict)}
    missing=[f'{i:02d}' for i in range(1,14) if f'{i:02d}' not in sections]
    if missing:
        raise RuntimeError('V161: secoes obrigatorias ausentes: '+', '.join(missing))

    caminho_pdf=Path(caminho_pdf)
    caminho_pdf.parent.mkdir(parents=True,exist_ok=True)
    cache=caminho_pdf.parent/'_v161_media_cache'
    cache.mkdir(parents=True,exist_ok=True)
    styles=_styles()
    border=_asset_bytes(_BORDER_B64); pf=_asset_bytes(_PF_B64); dicor=_asset_bytes(_DICOR_B64); wm=_asset_bytes(_WM_B64)
    W,H=A4
    # Conteudo começa abaixo do cabeçalho e sempre termina antes da moldura.
    frame=Frame(0.90*cm,1.18*cm,W-1.80*cm,H-6.15*cm,id='body',showBoundary=0,leftPadding=6,rightPadding=6,topPadding=5,bottomPadding=6)
    template=PageTemplate(id='v160',frames=[frame],onPage=_header_drawer(border,pf,dicor,wm))
    doc=BaseDocTemplate(str(caminho_pdf),pagesize=A4,pageTemplates=[template],title='Mandado e Dossie Operacional - Policia Federal DICOR',allowSplitting=1)

    meta=dict(payload.get('meta') or {})
    story=_first_pages(meta,sections,styles)
    for code in [f'{i:02d}' for i in range(1,14)]:
        story += _flow_section(sections[code],cache,materializer,styles)
        story.append(PageBreak())
    story += _motivation_page(sections,styles)+[PageBreak()]
    story += _signature_page(meta,styles)
    doc.build(story)
    _preflight(caminho_pdf)


def _preflight(path: Path) -> None:
    p=Path(path)
    if not p.exists() or p.stat().st_size<6000:
        raise RuntimeError('V161: PDF invalido ou vazio.')
    try:
        import fitz
        d=fitz.open(str(p)); text='\n'.join(page.get_text('text') or '' for page in d); d.close()
    except Exception:
        return
    if re.search(r'(?i)\bDENARC\b',text):
        raise RuntimeError('V161: termo DENARC ainda apareceu no PDF.')
    if re.search(r'(?i)\bDIC\b',text):
        raise RuntimeError('V161: termo DIC isolado ainda apareceu no PDF.')
    required=('POLÍCIA FEDERAL - DICOR','Buiu Gomes','Arthur Fleker','DELEGADO GERAL','DELEGADO DICOR','AGENTE RESPONSÁVEL','INGREDIENTES','PRODUTO FINAL')
    miss=[x for x in required if x not in text]
    if miss:
        raise RuntimeError('V161: preflight ausente: '+', '.join(miss))


def gerar_pdf_dossie(bot_module, dados: Dict[str,Any], caminho_pdf: Path) -> None:
    payload=(dados or {}).get('dossie_v124') if isinstance(dados,dict) else None
    if not isinstance(payload,dict):
        raise RuntimeError('V161: payload guiado 13/13 ausente. A mesa permanece aberta.')
    materializer=getattr(bot_module,'_v124_materializar_midia',None)
    render_payload(payload,Path(caminho_pdf),materializer=materializer)
    print(f'✅ V161 PDF no modelo do mandado anexado gerado: {Path(caminho_pdf).name}',flush=True)


def install(bot_module) -> None:
    """Troca somente o renderer do PDF; nao altera comandos, views ou tarefas."""
    if not hasattr(bot_module,'_V155_GERAR_PDF_BASE'):
        raise RuntimeError('V161: watchdog PDF do bot nao encontrado.')
    bot_module._V155_GERAR_PDF_BASE=lambda dados,caminho: gerar_pdf_dossie(bot_module,dados,caminho)
    try:
        bot_module.ASSINATURA_DELEGADO_GERAL_NOME='Buiu Gomes'
        bot_module.ASSINATURA_DELEGADO_DICOR_NOME='Arthur Fleker'
    except Exception:
        pass
    print('✅ V161 instalado - modelo visual do mandado anexado ativo; restante do bot intacto.',flush=True)
